driver_header:
#ifndef MCP3008_H
#define MCP3008_H

#include <stdint.h>
#include "rtthread.h"
#include "rtdevice.h"

struct rt_spi_device;

struct mcp3008_device {
    struct rt_spi_device *spi_device;
};

int mcp3008_init(struct mcp3008_device *dev, struct rt_spi_device *spi);
int mcp3008_read_channel(struct mcp3008_device *dev, uint8_t channel, uint16_t *value);

#endif /* MCP3008_H */

driver_source:
#include "mcp3008.h"
#include <stdint.h>
#include "rtthread.h"
#include "rtdevice.h"

int mcp3008_init(struct mcp3008_device *dev, struct rt_spi_device *spi)
{
    if (dev == RT_NULL || spi == RT_NULL) {
        return -1;
    }
    dev->spi_device = spi;
    return 0;
}

int mcp3008_read_channel(struct mcp3008_device *dev, uint8_t channel, uint16_t *value)
{
    if (dev == RT_NULL || dev->spi_device == RT_NULL || value == RT_NULL) {
        return -1;
    }
    if (channel > 7) {
        return -1;
    }

    uint8_t tx_buf[3];
    uint8_t rx_buf[3];

    tx_buf[0] = 0x01;
    tx_buf[1] = 0x80 | (channel << 4);
    tx_buf[2] = 0x00;

    rt_ssize_t ret = rt_spi_transfer(dev->spi_device, tx_buf, rx_buf, 3);
    if (ret != 3) {
        return -1;
    }

    uint16_t raw = ((uint16_t)(rx_buf[1] & 0x03) << 8) | (uint16_t)rx_buf[2];
    *value = raw;

    return 0;
}

